INSERT INTO regular_expressions(name,pattern,regex101_id,description) VALUES ('Xvid','\b(Xvid)\b',NULL,'Xvid is a video codec based on the MPEG-4 Part 2 standard, designed for efficient compression while maintaining good visual quality. It is commonly used for encoding videos into smaller file sizes suitable for online sharing or storage, often paired with MP3 or AAC audio.');
